import os
from ta_moler.device.cus import CUS  # type: ignore
from ta_moler.device.rtg import RTG  # type: ignore
from typing import List, Optional
from moler.util.moler_test import MolerTest  # type: ignore
from moler.exceptions import CommandFailure, ExecutionException  # type: ignore
from taf.ul.sc.rtg import Executor  # type: ignore
from taf.ul.sc.rtg import Workstation  # type: ignore
from taf.ul.sc.rtg import Controller  # type: ignore
from taf.ul.sc.rtg.update_and_wait_until_up import UpdateAndWaitUntilUp  # type: ignore
from taf.ul.sc.perf.devices.ue.generic_ue import GenericUe
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console, log_info_to_console
from taf.ul.sc.perf.util.recovery_observer_manager import RecoveryObserverManager


class GenericRtgCus(GenericUe):
    def __init__(self,
                 executor: Optional[Executor] = None,
                 workstation: Optional[Workstation] = None,
                 controllers: Optional[List[Controller]] = None,
                 ):

        super(GenericRtgCus, self).__init__()
        if executor is None:
            raise ValueError("Executor is required")
        if workstation is None:
            raise ValueError("Workstation is required")
        self.executor = executor
        self.ws = workstation
        self.ctrls = controllers
        self.name = self.executor.name
        self.ws_name = self.ws.name if self.ws else self.executor.ws_name
        self.started_scenarios: List[str] = []

        self._recovery = None

    @log_function_status_to_console(msg="Upload UE CAP file", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def upload_ue_cap(self, ue_cap_file):

        self.ws.upload_ue_cap(ue_cap_file, raise_exception=True)

    @log_function_status_to_console(msg="Upload UE DB file", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def upload_ue_db(self, ue_db_file):

        self.ws.upload_ue_db(ue_db_file, raise_exception=True)

    @log_function_status_to_console(msg="Change configuration file", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def change_configuration_file(self, configuration_file):

        self.ws.upload_configuration(configuration_file, raise_exception=True)
        self.disconnect_devices_and_restart_executor_if_needed()
        self.executor.update_local_configuration(path=self._get_default_configuration_path())
        self.restart_and_wait_until_up()

    @log_function_status_to_console(msg="Update configuration", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def change_configuration(self, params):

        self.ws.update_configuration(params_to_update=params)
        self.disconnect_devices_and_restart_executor_if_needed()
        self.executor.update_local_configuration(path=self._get_default_configuration_path())
        self.restart_and_wait_until_up()

    def disconnect_devices_and_restart_executor_if_needed(self):
        try:
            self.executor.disconnect_all_devices()
        except CommandFailure as exc:
            if "Test already in progress. Cannot proceed" in str(exc):
                self._restart_executor_after_exception(execute_after_restart=self.executor.disconnect_all_devices)
            else:
                raise exc

    def _get_default_configuration_path(self):
        path = None
        if isinstance(self.executor.device, CUS):
            path = '/opt/cus/etc/cus.ini'
        elif isinstance(self.executor.device, RTG):
            path = '/opt/rtg/etc/rtg.ini'

        return path

    @log_function_status_to_console(msg="Starting scenario", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_scenario(self, scenario_name):
        results = self.executor.start_rtg_scenario(scenario_name=scenario_name)
        self.started_scenarios.append(results)

    @log_function_status_to_console(msg="Stopping scenario", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_scenario(self):
        try:
            self.executor.stop_rtg_scenario()
        except CommandFailure as exc:
            if "Test already in progress. Cannot proceed" in str(exc):
                self._restart_executor_after_exception(execute_after_restart=self.executor.stop_rtg_scenario)
            else:
                raise exc

    @log_function_status_to_console(msg="Copy scenario file to WS", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def copy_scenario_file(self, source_scenario_path, destination_dir='/home/rtg/test/scenarios/'):
        super(GenericRtgCus, self).copy_scenario_file(source_scenario_path=source_scenario_path,
                                                      destination_dir=destination_dir)

    def get_version(self):
        return self.executor.version

    def get_ue_type(self):
        return self.executor.name

    @log_debug_function_info()
    def synchronize_bts_link(self, small_cell_enbs=()):
        if small_cell_enbs:
            self.executor.synchronize_small_cell_link(enbs=[enb.bts for enb in small_cell_enbs])

    @log_function_status_to_console(msg="Collect conf files: UE_CAP/UE_DB", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_configuration(self, log_dir):
        if not self.started_scenarios:
            MolerTest.warning("Scenario not started. Cannot download RTG configuration")
            return

        last_execution = self.started_scenarios[-1]
        execution_dir = os.path.join(last_execution['SCENARIO'], last_execution['QUEUED_TIME'])
        self.ws.collect_rtg_configuration_file(execution_dir, log_dir)
        self.ws.collect_dhcp_configuration_file(log_dir)
        self.ws.collect_ue_capabilities_file(execution_dir, log_dir)
        self.ws.collect_ue_db_file(execution_dir, log_dir)
        self.ws.collect_scenario_file(execution_dir=execution_dir,
                                      scenario_name=last_execution['SCENARIO'],
                                      destination_dir=log_dir)

    @log_function_status_to_console(msg="Collect logs: CTRL_MMI/SYSLOG", log_hierarchy=2,
                                    ignore_exception=True, add_name_prefix=True)
    @log_debug_function_info()
    def collect_debug_logs(self, log_dir):
        for started_scenario in self.started_scenarios:
            execution_dir = os.path.join(started_scenario['SCENARIO'], started_scenario['QUEUED_TIME'])
            self.ws.collect_mmi_ctrl_files(execution_dir=execution_dir,
                                           destination_dir=log_dir)
            self.ws.collect_syslog_ctrl_files(execution_dir=execution_dir,
                                              destination_dir=log_dir)

    @log_function_status_to_console(msg="Collect test report", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_report(self, log_dir):
        for started_scenario in self.started_scenarios:
            self.ws.collect_test_report(execution_dir=os.path.join(started_scenario['SCENARIO'],
                                                                   started_scenario['QUEUED_TIME']),
                                        destination_dir=log_dir)

    @log_debug_function_info()
    def restart_and_wait_until_up(self):
        self._check_and_wait_for_not_connected_controllers()
        if self.ctrls:
            cru = UpdateAndWaitUntilUp(executor=self.executor, workstation=self.ws, ctrls=self.ctrls)
            cru.config_remote_update_and_wait_until_controllers_up()
        else:
            self.executor.update_remote_configuration()

    @log_function_status_to_console(msg="Start recovery observers", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_recovery_observers(self, action='test_recovery', recovery_params=None, before=None, after=None):
        self._recovery = RecoveryObserverManager(device=self.executor.device,
                                                 events=[{'event_name': 'device_connection_lost'},
                                                         {'event_name': 'sectors_inoperational'},
                                                         {'event_name': 'sector_not_receiving_ovhd'},
                                                         {'event_name': 'dsp_crash'}])

        self._recovery.start_recovery_observers(action, recovery_params, before, after)

    @log_function_status_to_console(msg="Stop recovery observers", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_recovery_observers(self):
        self._recovery.stop_recovery_observers()

    def is_scenario_running(self):
        status = self.executor.get_status()
        if status.get('queue', None):
            return True
        return False

    def restart(self):
        self._check_and_wait_for_not_connected_controllers()
        self.executor.update_remote_configuration()

    def perform_additional_actions_before_start_scenario(self):
        ctrls = self.executor.get_enbsim_ctrls()
        if ctrls:
            self.executor.remote_restart(target=" ".join(["ctrl-{}".format(ctrl_id) for ctrl_id in ctrls]))

    def _check_and_wait_for_not_connected_controllers(self, delay=30, tries=10):
        if self.ws.get_not_connected_controllers() and tries > 0:
            MolerTest.sleep(delay)
            self._check_and_wait_for_not_connected_controllers(delay, tries - 1)

    @log_function_status_to_console(msg="Check if all CTRLs are connected", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def check_if_connected_and_if_not_perform_recovery(self):
        MolerTest.sleep(60)  # wait a minute for RTG/CUS MIB/SIB stabilization
        try:
            self.executor.connect_all_devices()
        except CommandFailure as err:
            e = str(err)
            msg = e[e.find('>>') + 2:e.rfind('<<')]
            if 'Error connecting to' in msg:
                log_info_to_console(msg="cm connect failed with: {}. Waiting for CTRL(s) to be up".format(msg),
                                    log_hierarchy=2)
                self._check_and_wait_for_not_connected_controllers(tries=20)
                return False
            if 'is not receiving overhead messages' in msg:
                log_info_to_console(
                    msg="cm connect failed with: {}. Trying to recover by performing reboot".format(msg),
                    log_hierarchy=2)
                self.executor.remote_restart()
                self._check_and_wait_for_not_connected_controllers(tries=20)
                return False
            if "Test already in progress. Cannot proceed" in msg:
                log_info_to_console(msg="cm connect failed with: {}.".format(msg), log_hierarchy=2)
                self._restart_executor_after_exception()
                return False
            else:
                raise err
        return True

    def get_used_rrh_types(self):
        return self.executor.config()

    def _restart_executor_after_exception(self, execute_after_restart=None):
        log_info_to_console(msg="Trying to recover by performing executor reset", log_hierarchy=2)
        self.ws.restart_executor()
        self._wait_for_executor()

        if execute_after_restart:
            execute_after_restart()

    def _wait_for_executor(self, max_tries=5):
        is_executor_on = False
        while not is_executor_on and max_tries:
            try:
                max_tries -= 1
                self.executor.connect_all_devices()
                is_executor_on = True
            except CommandFailure:
                MolerTest.sleep(30)

        if not is_executor_on:
            raise ExecutionException("Executor did not work properly after reset")

    def align_rtg_cell_to_radio_cell(self):
        """
        Align RTG cell to radio cell.
        :return: None
        """
        self.executor.align_rtg_cell_to_radio_cell()


    def is_rf_cell_in_configuration(self):
        """
        Check if RF cell is in configuration.
        :return: True if RF cell is in configuration, False otherwise.
        """
        return self.executor.is_rf_cell_in_configuration()
